kernels.wgsl:
@group(0) @binding(0) var<storage, read> b0: array<f32>;
@group(0) @binding(1) var<storage, read> b1: array<f32>;
@group(0) @binding(2) var<storage, read> b2: array<f32>;
@group(0) @binding(3) var<storage, read> b3: array<f32>;
@group(0) @binding(4) var<storage, read> b4: array<f32>;
@group(0) @binding(5) var<storage, read> b5: array<f32>;
@group(0) @binding(6) var<storage, read> b6: array<f32>;
@group(0) @binding(7) var<storage, read_write> bout: array<f32>;

@compute @workgroup_size(1024)
fn main(@builtin(local_invocation_index) lid: u32, @builtin(workgroup_id) wid: vec3<u32>, @builtin(num_workgroups) nwg: vec3<u32>) {
    let tid: i32 = i32(lid);
    let bid: i32 = i32(wid.x) + i32(wid.y) * i32(nwg.x);
    if (bid >= 1i) { return; }
    var v_in0: f32 = 0.0;
    var v_v0: f32 = 0.0;
    var v_in1: f32 = 0.0;
    var v_v1: f32 = 0.0;
    var v_in2: f32 = 0.0;
    var v_in3: f32 = 0.0;
    var v_in4: f32 = 0.0;
    var v_v2: f32 = 0.0;
    var v_v3: f32 = 0.0;
    var v_in5: f32 = 0.0;
    var v_v4: f32 = 0.0;
    var v_in6: f32 = 0.0;
    var v_in7: f32 = 0.0;
    var v_in8: f32 = 0.0;
    var v_v5: f32 = 0.0;
    var v_v6: f32 = 0.0;
    var v_in9: f32 = 0.0;
    var v_v7: f32 = 0.0;
    var v_v8: f32 = 0.0;
    var n_e: i32 = 0i;
    n_e = ((1024i * bid) + tid);
    if (n_e < 30i) {
        v_in0 = b6[((5i * ((n_e / 5i) % 3i)) + (n_e % 5i))];
        v_v0 = (1.0 - v_in0);
        v_in1 = b5[((5i * ((n_e / 5i) % 3i)) + (n_e % 5i))];
        v_v1 = (1.0 - v_in1);
        v_in2 = b0[((min((max((10i * (n_e % 5i)), 0i) / 10i), 4i) + (5i * min((max((6i * ((n_e / 5i) % 3i)), 0i) / 6i), 2i))) + (15i * (n_e / 15i)))];
        v_in3 = b0[((min(((max((10i * (n_e % 5i)), 0i) / 10i) + 1i), 4i) + (5i * min((max((6i * ((n_e / 5i) % 3i)), 0i) / 6i), 2i))) + (15i * (n_e / 15i)))];
        v_in4 = b4[((5i * ((n_e / 5i) % 3i)) + (n_e % 5i))];
        v_v2 = (v_in3 * v_in4);
        v_v3 = fma(v_v1, v_in2, v_v2);
        v_in5 = b2[((5i * ((n_e / 5i) % 3i)) + (n_e % 5i))];
        v_v4 = (1.0 - v_in5);
        v_in6 = b0[(((5i * min(((max((6i * ((n_e / 5i) % 3i)), 0i) / 6i) + 1i), 2i)) + min((max((10i * (n_e % 5i)), 0i) / 10i), 4i)) + (15i * (n_e / 15i)))];
        v_in7 = b0[((min(((max((10i * (n_e % 5i)), 0i) / 10i) + 1i), 4i) + (5i * min(((max((6i * ((n_e / 5i) % 3i)), 0i) / 6i) + 1i), 2i))) + (15i * (n_e / 15i)))];
        v_in8 = b1[((5i * ((n_e / 5i) % 3i)) + (n_e % 5i))];
        v_v5 = (v_in7 * v_in8);
        v_v6 = fma(v_v4, v_in6, v_v5);
        v_in9 = b3[((5i * ((n_e / 5i) % 3i)) + (n_e % 5i))];
        v_v7 = (v_v6 * v_in9);
        v_v8 = fma(v_v0, v_v3, v_v7);
        bout[(((5i * ((n_e / 5i) % 3i)) + (n_e % 5i)) + (15i * (n_e / 15i)))] = v_v8;
    }
}
